import React, { Component } from 'react'
import { connect } from 'react-redux'
import { Button, Icon, Row, Col, Input, Alert, Tooltip, Table, Modal, DatePicker, Checkbox, notification } from 'antd'
import swal from 'sweetalert2'
import _ from 'lodash'
import QueryString from 'query-string'
import moment from 'moment-timezone'
import LayoutContent from '../../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../../components/utility/layoutWrapper'
import gocarAction from '../../../redux/gocar/actions'
import QuerySearchBuilder from '../../../../helpers/querySearchBuilder'
import GocarTableStyled from './gocarTable.style'
import Cookies from 'universal-cookie'
import { tableColumns } from '../GocarComponents/tableData'

const cookies = new Cookies()

const { getGocarSimpleData, sendGocarReport } = gocarAction

class GocarSimpleTable extends Component {
  constructor (props) {
    super(props)
    this.state = {
      searchText: '',
      searchTextQuery: {},
      limit: 10,
      offset: 0,
      showDownloadModal: false,
      registrationStartDate: undefined,
      registrationEndDate: undefined,
      downloadAllData: false
    }
  }

  componentDidMount () {
    const querySearch = QueryString.parse(this.props.location.search)
    this.fetch(querySearch)
  }

  fetch = (params = {}) => {
    const { offset, limit, orderBy, startDate, endDate } = params
    const offsetNumber = Number(offset) || 0
    const limitNumber = Number(limit) || 10
    delete params.offset
    delete params.limit

    this.setState({
      searchText: '',
      orderIdentifier: orderBy,
      limit: limitNumber,
      offset: offsetNumber
    })
    this.props.getGocarSimpleData({
      ...params,
      orderBy,
      tagID: 'null',
      limit: limitNumber,
      offset: offsetNumber,
      startDate,
      endDate,
      policyState: 'COMPLETED'
    })
  }

  downloadExcel = () => {
    const { profileData } = this.props
    const { registrationStartDate, registrationEndDate } = this.state
    const body = { registration_start_date: registrationStartDate, registration_end_date: registrationEndDate }
    const filteredData = _.pickBy(body, _.identity)

    swal({
      title: 'Report will send to your email ',
      input: 'email',
      inputValue: profileData.email,
      showCancelButton: true,
      confirmButtonText: 'Send',
      showLoaderOnConfirm: true,
      preConfirm: mail => {
        this.props.sendGocarReport({
          query: { purpose: 'go_car_simple_gojekid', productKey: 'go-car-simple' },
          body: { email_id: mail, ...filteredData }
        })
      },
      allowOutsideClick: () => false
    }).then(result => {
      this.setState({ registrationEndDate: undefined, registrationStartDate: undefined, downloadAllData: false })
      if (result.dismiss !== 'cancel') {
        swal({ type: 'success', title: '', text: 'success' })
      }
    })
  }

  onClearFilter = () => {
    const { location } = this.props
    this.props.history.push({ pathname: location.pathname, search: '' })
    this.fetch()
  }

  onFilterChange (val) {
    cookies.set('querySearch', val.target.value, { path: '/' })
    this.setState({ searchInput: val.target.value })
    this.state.gridOptions.api.setQuickFilter(val.target.value)
  }

  onView = (id) => {
    this.props.history.push({ pathname: `/gocar/simple/${id}`, state: { params: { internalID: id } } })
  }

  handlePageChange = (val) => {
    const { location } = this.props
    const { current, pageSize } = val
    const searchText = {}
    searchText['offset'] = (current - 1) * pageSize
    searchText['limit'] = 10
    const search = QuerySearchBuilder(searchText)
    this.props.history.push({ pathname: location.pathname, search })
    this.fetch(searchText)
  }

  handleSearch = (selectedKeys, dataIndex) => {
    const { location, history } = this.props
    const params = new URLSearchParams(location)
    delete params['limit']
    delete params['offset']
    params[dataIndex] = selectedKeys
    const search = QuerySearchBuilder(params)
    history.push({ pathname: location.pathname, search })
    this.fetch(params)
  }

  handleDownload = () => {
    const { registrationStartDate, registrationEndDate, downloadAllData } = this.state

    if (!downloadAllData && (!registrationEndDate || !registrationStartDate)) {
      notification['error']({ message: 'Please select registration dates' })
    } else {
      if (downloadAllData) {
        this.setState({ registrationStartDate: undefined, registrationEndDate: undefined })
      }
      this.setState({ showDownloadModal: false })
      this.downloadExcel()
    }
  }

  getColumnSearchProps = dataIndex => ({
    filterDropdown: ({ setSelectedKeys, selectedKeys }) => (
      <div style={{ padding: 8 }}>
        <Input
          ref={node => {
            this.searchInput = node
          }}
          placeholder={`Search ${dataIndex}`}
          value={selectedKeys[0]}
          onChange={e => setSelectedKeys(e.target.value ? [e.target.value] : [])}
          onPressEnter={() => this.handleSearch(selectedKeys, dataIndex)}
          style={{ width: 188, marginBottom: 8, display: 'block' }}
        />
        <Button
          type='primary'
          onClick={() => this.handleSearch(selectedKeys, dataIndex)}
          icon='search'
          size='small'
          style={{ width: 90, marginRight: 8 }}
        >
          Search
        </Button>
      </div>
    ),
    filterIcon: filtered => (
      <Icon type='search' style={{ color: filtered ? '#1890ff' : undefined }} />
    ),
    onFilter: (value, record) =>
      record[dataIndex]
        .toString()
        .toLowerCase()
        .includes(value.toLowerCase()),
    onFilterDropdownVisibleChange: visible => {
      if (visible) {
        setTimeout(() => this.searchInput.select())
      }
    }
  })

  render () {
    const { gocarData, goCarDataLoading } = this.props
    const { showDownloadModal, downloadAllData, registrationStartDate, registrationEndDate } = this.state
    const { metadata = {} } = gocarData

    const columns = [
      {
        title: 'Action',
        dataIndex: 'InternalID',
        key: 'action',
        render: (item) => <Icon type='eye' onClick={() => this.onView(item)} />
      },
      ...tableColumns(this)
    ]

    return (
      <GocarTableStyled>
        <Modal
          visible={showDownloadModal}
          title='Download Missing Gojek ID Data'
          onCancel={() => this.setState({
            showDownloadModal: false,
            registrationStartDate: undefined,
            registrationEndDate: undefined,
            downloadAllData: false
          })}
          onOk={this.handleDownload}
        >
          <GocarTableStyled>
            <Row>
              <Col span={12}>
                Registration Start Date
              </Col>
              <Col span={12}>
                <DatePicker
                  disabled={downloadAllData}
                  value={registrationStartDate && moment(registrationStartDate)}
                  onChange={(date, dateString) => this.setState({ registrationStartDate: dateString })}
                  format='YYYY-MM-DD 00:00:00'
                  className='datepicker'
                />
              </Col>
            </Row>
            <Row>
              <Col span={12}>
                Registration End Date
              </Col>
              <Col span={12}>
                <DatePicker
                  disabled={downloadAllData}
                  value={registrationEndDate && moment(registrationEndDate)}
                  onChange={(date, dateString) => this.setState({ registrationEndDate: dateString })}
                  format='YYYY-MM-DD 23:59:59'
                  className='datepicker'
                />
              </Col>
            </Row>
            <Row>
              <Checkbox
                checked={downloadAllData}
                onChange={(e) => this.setState({ downloadAllData: e.target.checked })}
              />
                Download All Data
            </Row>
          </GocarTableStyled>
        </Modal>
        <LayoutContentWrapper className='simple-table'>
          {this.state.error && (
            <Row className='row-error'>
              <Col span={24}>
                <Alert className='error-alert' message='Ooops, something went terribly wrong!' type='error' closeText='Close' />
              </Col>
            </Row>
          )}
          <LayoutContent className='table-container'>
            <Row gutter={16}>
              <Col className='gutter-row-export-csv table-col' span={24}>
                <h3>Gocar Simple</h3>
                <div className='btn-container'>
                  <Button
                    className='btn-clear'
                    onClick={this.onClearFilter}
                  >
                    <Icon type='cross' />Clear Filters
                  </Button>
                  <Tooltip placement='topLeft' title='This will email the excel of gojek drivers for which gojek id is blank'>
                    <Button
                      className='btn-download'
                      onClick={() => this.setState({ showDownloadModal: true })}
                    ><Icon type='cloud' /> Download Missing Gojek Driver</Button>
                  </Tooltip>
                </div>
              </Col>
            </Row>
            <Row>
              <Table
                dataSource={gocarData.goCarList}
                columns={columns}
                className='table'
                bordered
                pagination={{
                  pageSize: 10,
                  total: Number(metadata.total_records),
                  current: (metadata.offset / metadata.limit) + 1
                }}
                onChange={this.handlePageChange}
                loading={!!goCarDataLoading}
              />
            </Row>
          </LayoutContent>
        </LayoutContentWrapper>
      </GocarTableStyled>
    )
  }
}

export default connect(
  state => ({
    gocarData: state.Gocar,
    dataProfile: state.Auth.profile,
    goCarDataLoading: state.Loading.GET_GOCAR_SIMPLE_DATA,
    profileData: state.Auth.profile
  }),
  {
    getGocarSimpleData,
    sendGocarReport
  }
)(GocarSimpleTable)
